local module = {}
module.__index = module

function module.new(
	eventBus: IEventBus,
	luaProtocols: ILuaProtocols,
	protoImplementionsProviders: IEnumerable<IProtoImplementionsProvider>
)
	local self = setmetatable({}, module)
	self.EventBus = eventBus
	self.LuaProtocols = luaProtocols
	self.ProtoImplementions = {}
	for _, protoImplementionsProvider in protoImplementionsProviders do
		for name, moduleScript in protoImplementionsProvider() do
			self.ProtoImplementions[name] = moduleScript
		end
	end
	return self
end

function module:GetProtocol(protocol: string)
	return self.LuaProtocols[protocol]
end

function module:HasProtocol(protocol: string): boolean
	return self.LuaProtocols[protocol] ~= nil
end

-- 确保可以接收协议
function module:AssertObservable(protocol: string)
	assert(self.EventBus, "EventBus not provided")
	assert(self:HasProtocol(protocol), "Protocol not found:" .. protocol)
end

-- 获取协议实现
function module:GetProtocolImplemention(protocol: string)
	return self.ProtoImplementions[protocol]
end

-- 获取所有协议
function module:GetAllProtocols(): { [string]: {} }
	return self.LuaProtocols
end

return module
